namespace Game.Core.Contracts.Status;

/// <summary>
/// Canonical status contract for Task 5 acceptance semantics.
/// </summary>
public sealed record Status(
    string StableId,
    string StatusId,
    StatusType StatusType,
    int Stacks,
    int DurationTurns,
    string SourceId,
    ExpiresTiming ExpiresTiming,
    int Strength
)
{
    public Status StackWith(Status incoming)
    {
        return FromInstance(ToInstance().StackWith(incoming.ToInstance()));
    }

    public Status AccumulateDuration(int deltaTurns)
    {
        return FromInstance(ToInstance().AccumulateDuration(deltaTurns));
    }

    public Status Decay(int turns = 1)
    {
        return FromInstance(ToInstance().Decay(turns));
    }

    internal StatusInstance ToInstance()
    {
        return new StatusInstance(
            StableId: StableId,
            StatusId: StatusId,
            StatusType: StatusType,
            Stacks: Stacks,
            DurationTurns: DurationTurns,
            SourceId: SourceId,
            ExpiresTiming: ExpiresTiming,
            Strength: Strength);
    }

    internal static Status FromInstance(StatusInstance instance)
    {
        return new Status(
            StableId: instance.StableId,
            StatusId: instance.StatusId,
            StatusType: instance.StatusType,
            Stacks: instance.Stacks,
            DurationTurns: instance.DurationTurns,
            SourceId: instance.SourceId,
            ExpiresTiming: instance.ExpiresTiming,
            Strength: instance.Strength);
    }
}

namespace Game.Core.Contracts.Status;

/// <summary>
/// Status instance applied to a combatant.
/// </summary>
public sealed record StatusInstance(
    string StableId,
    string StatusId,
    StatusType StatusType,
    int Stacks,
    int DurationTurns,
    string SourceId,
    ExpiresTiming ExpiresTiming,
    int Strength
)
{
    public StatusInstance StackWith(StatusInstance incoming)
    {
        return StatusOperations.Stack(this, incoming);
    }

    public StatusInstance AccumulateDuration(int deltaTurns)
    {
        return StatusOperations.AccumulateDuration(this, deltaTurns);
    }

    public StatusInstance Decay(int turns = 1)
    {
        return StatusOperations.Decay(this, turns);
    }
}

namespace Game.Core.Contracts.Status;

/// <summary>
/// Pure status operation helpers for stack, duration and deterministic ordering.
/// </summary>
public static class StatusOperations
{
    public const string StrengthStatusId = "status.strength";
    public const string RageStatusId = "status.rage";

    public static bool CanDispel(StatusInstance status)
    {
        if (status.StatusType == StatusType.RuleModifier)
        {
            return false;
        }

        if (string.Equals(status.StatusId, StrengthStatusId, StringComparison.Ordinal))
        {
            return false;
        }

        return status.StatusType == StatusType.Debuff;
    }

    public static bool IsRage(StatusInstance status)
    {
        return string.Equals(status.StatusId, RageStatusId, StringComparison.Ordinal);
    }

    public static IReadOnlyList<StatusInstance> SortByStableId(IEnumerable<StatusInstance> statuses)
    {
        return statuses
            .OrderBy(s => s.StableId, StringComparer.Ordinal)
            .ThenBy(s => s.StatusId, StringComparer.Ordinal)
            .ToArray();
    }

    public static IReadOnlyList<StatusInstance> Dispel(IEnumerable<StatusInstance> statuses)
    {
        return statuses
            .Where(status => !CanDispel(status))
            .ToArray();
    }

    public static StatusInstance Stack(StatusInstance current, StatusInstance incoming)
    {
        if (!IsSameStatus(current, incoming))
        {
            return current;
        }

        return current with
        {
            Stacks = Math.Max(0, current.Stacks + Math.Max(0, incoming.Stacks)),
            DurationTurns = Math.Max(0, current.DurationTurns + Math.Max(0, incoming.DurationTurns)),
            Strength = Math.Max(0, current.Strength + Math.Max(0, incoming.Strength)),
        };
    }

    public static StatusInstance AccumulateDuration(StatusInstance current, int deltaTurns)
    {
        return current with
        {
            DurationTurns = Math.Max(0, current.DurationTurns + Math.Max(0, deltaTurns)),
        };
    }

    public static StatusInstance Decay(StatusInstance current)
    {
        return Decay(current, 1);
    }

    public static StatusInstance Decay(StatusInstance current, int turns)
    {
        return current with
        {
            DurationTurns = Math.Max(0, current.DurationTurns - Math.Max(0, turns)),
        };
    }

    private static bool IsSameStatus(StatusInstance left, StatusInstance right)
    {
        return string.Equals(left.StatusId, right.StatusId, StringComparison.Ordinal) &&
               left.StatusType == right.StatusType;
    }
}

